# November 20, 2026: Lake George village, Bolton, Warrensburg, Chester, Horicon, Johnsburg (Riparius), Stony Creek and
# Hague, in Warren County, New York. Drawn at random by tools/choose.py --state ny (region adk, which offered
# Warrensburg among others); start.py found four Atlas places within 15 km of Warrensburg (all in Lake George village,
# none of them the forts, the courthouse or the churches) and none round Chestertown or Bolton Landing.
# Sources were opened in this session: Wikipedia as raw text (tools/wiki_raw.py); National Register forms that NPGallery
# has as text (Caldwell Presbyterian Church 16000164, Delaware and Hudson Passenger Station 13000310, Heintzelman
# Library 100001249); HMdb marker pages; the NYS DEC page for the Lake George Battlefield day-use area; the
# lakegeorge.com Colonial Wars walking tour (Bateaux Below text); the Lake George Historical Association's hours page;
# Clio; The Sembrich's visit page; St. James' Church's own site and the Diocese of Albany; the Pomeroy Foundation's
# Riverside Station page; Warren County's Horicon marker sheet; the Lake George Chamber's pages on Caldwell
# Presbyterian and the Mountainside Library; an I LOVE NY news post for Fort William Henry's 2026 season.
# NPGallery returned its one-page placeholder (form not read) for the Battlefield Park district 11000971, the old
# courthouse 73001282, Warrensburg Mills 75001232, Hamlet of Warrensburgh 01000292, Mixter 02001051, Sembrich 02000799,
# Silver Bay 80002785, Riverside 97000471, Stony Creek 10000031 and Chestertown 77000984.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
BATCH={'key':'adk_pbhk','label':'Lake George, Bolton, Warrensburg and northern Warren County','added':'2026-11-20 12:40'}
HM=lambda m,t: L('HMdb: '+t,'https://www.hmdb.org/m.asp?m='+m)
NR=lambda ref,t: L('National Register form: '+t+' (PDF)','https://npgallery.nps.gov/NRHP/GetAsset/NRHP/'+ref+'_text')
DEC=L('NYS DEC: Lake George Battlefield Day Use Area','https://dec.ny.gov/places/lake-george-battlefield-day-use-area')
PLACES=[
# ---- Lake George village ----
N('fort-george-ruins-lake-george','Fort George ruins (the 1759 bastion), Lake George Battlefield Park','Lake George','adk','fort','ruins',43.41495,-73.7068,'site','public','walk','forts','1759',
  'Fort George was begun in 1759 on the high ground east of the burned Fort William Henry, as a stone-and-lime fort with walls about 14 feet thick. Only one bastion was ever finished; Jeffery Amherst wrote in 1760 that it was very neat and mounted 15 guns, but was small and a bad defence. The battlefield park round it was the site of the 1755 Battle of Lake George, a camp throughout the French and Indian War, and a hospital and supply base early in the Revolution.',
  'The stone walls of the one finished bastion, which the walking tour gives as 15 to 20 feet high. Excavations by David Starbuck have traced foundations inside the stockaded fort, hut sites and the outline of the fort itself; the DEC page says ruins of other buildings and fortifications lie throughout the park, with monuments and interpretive panels. Damaging the walls is illegal.',
  'The one bastion of a fort the British never finished.',
  'In Lake George Battlefield Park, run by the NYS Department of Environmental Conservation, 34 Fort George Road. The DEC page gives the day-use area\'s 2026 season as May 23 to September 7, with a fee of $10 a car, $5 a motorcycle; no pets in DEC day-use areas. Facility phone on the DEC page. The lot OpenStreetMap maps on Fort George Park Road is a boat-storage yard on the aerial, and the DEC\'s own GPS point falls in woods, so no parking point is given: use the day-use area\'s entrance on Fort George Road.',
  [DEC,L('lakegeorge.com Colonial Wars walking tour, stop 11: Fort George Ruins','https://lakegeorge.com/things-to-do/walking-tour/11-fort-george-ruins'),W('Lake George Battlefield Park')],
  brick='no',hours='Day-use season May 23 to September 7 (2026); fee $10 a car'),
N('fort-william-henry-museum','Fort William Henry (the 1950s reconstruction)','Lake George','adk','fort','standing',43.4203,-73.7111,'site','open','drive','forts','1755–1757; rebuilt 1950s',
  'The British built Fort William Henry in 1755 at the head of Lake George, a square fort with bastions at the corners and two-storey wooden barracks round the parade ground; the magazine was in the northeast bastion and the hospital in the southeast. After the French siege of 1757 it was burned, and the site lay abandoned for two centuries, its ruins a tourist stop in the 1800s. A replica was built on the site in the 1950s and is run as a living-history museum.',
  'The reconstructed log-and-earth fort with its four bastions; HMdb has markers for the northeast, northwest and southwest bastions. This is a rebuild, not the 1755 fabric. Interior not checked.',
  'A fort burned in 1757 and rebuilt on its own ground in the 1950s.',
  'A private museum on Canada Street at Beach Road, run by the Fort William Henry Corporation; admission charged. Its own site (fwhmuseum.com) refused the page tool, so the hours are from the operator\'s 2026 season announcement as posted on I LOVE NY, which gave winter weekends only; summer hours not read. Several lots surround it (not checked whether paid).',
  [W('Fort William Henry'),L('I LOVE NY: Fort William Henry gears up for a 270th anniversary season (2026)','https://www.iloveny.com/thebeat/post/fort-william-henry-gears-up-for-a-landmark-270th-anniversary-season/'),HM('15801','Northeast Bastion')],
  brick='no',hours='Winter 2026: weekends to March 8, 10:30 a.m. to 4 p.m.; summer hours not read'),
N('old-warren-county-courthouse','Old Warren County Courthouse (Lake George Historical Association museum)','Lake George','adk','civic','standing',43.42591,-73.71175,'exact','open','drive','','1845–1890s',
  'Warren County\'s government sat here from 1813 to 1963. The first courthouse, of 1817, burned in 1843; the present one was built in 1845 and grew in five stages to the 1890s, not all of which survive. Left empty when the county moved out, it was saved by the Lake George Historical Association, formed in 1964, which has run a museum in it since 1968; the Lake George Arts Project shares it.',
  'Three linked sections running from Canada Street back towards the lake: the judges\' chambers with a two-stage clock tower on the front, the original courthouse and the jail wing, all of red-brick-faced masonry (a Wikimedia photograph of the front shows red brick) on a limestone foundation with a coloured slate roof. Inside, the museum shows the old courtroom and the jail cells (Clio). A French cannonball was dug up on the grounds in the 1970s; the site was close to Montcalm\'s first battery of 1757.',
  'The county\'s courthouse for 150 years, cells and all.',
  'At 290 Canada Street (US 9) at Amherst Street. The association\'s own page gives the 2026 hours and asks visitors to telephone before making the trip, as hours change with staffing; the season ended October 20. Street parking in the village (not checked).',
  [W('Old Warren County Courthouse Complex'),L('Lake George Historical Association: contact and hours','https://lakegeorgehistorical.org/contact'),L('Clio: Old Warren County Courthouse','https://theclio.com/entry/18301'),HM('17385','Old Courthouse')],
  brick='yes',hours='Mid-May to October 20 (2026): June and September Fri to Sun 11 a.m. to 4 p.m.; July and August Tue and Fri to Sun 11 a.m. to 4 p.m., Wed and Thu 3 to 8 p.m.'),
N('dh-station-lake-george','Delaware & Hudson passenger station, Lake George','Lake George','adk','rail','standing',43.42022,-73.70943,'exact','view','drive','stations','1909–1911',
  'The Delaware and Hudson built this station in 1909 to 1911 to plans by the New York architects Ludlow & Peabody, after the Fort William Henry Hotel burned in 1909; it replaced a station of 1882 and was the base for the company\'s railroad and steamboat business on the lake. Passenger service to Lake George ended with the closing of the station in 1958. It was listed on the National Register in 2013.',
  'A one-storey stuccoed building in a Mediterranean Revival style with a tall tower carrying statues and a tile frieze at its top stage, an entrance loggia with sawn rafter tails, and arches now filled with board and batten. The 2013 form says the waiting room under its barrel-vaulted ceiling keeps its plan, with original plaster and woodwork, the copper frieze and cornice of the ticket and telegraph office, lamps and panelled doors, though fake hewn beams have been added. Present use and whether it opens not checked.',
  'The D&H station where the trains met the steamboats.',
  'At 57 Beach Road, opposite the Lake George Steamboat Company dock. Seen from Beach Road; who owns it now and whether the inside is open were not checked.',
  [NR('13000310','Delaware and Hudson Passenger Station'),W('Lake George station')],brick='no'),
N('caldwell-presbyterian-church','Caldwell Presbyterian Church','Lake George','adk','worship','standing',43.42486,-73.71503,'site','view','drive','','1855–1856',
  'The congregation is named for James Caldwell, who put up the first church in Lake George in 1810 on Canada Street. The present church was built in 1855 and 1856 as a Greek Revival meetinghouse with a tower, and a social hall was added behind it in 1893. It stands diagonally across the corner from St. James\' Episcopal Church, and was listed on the National Register in 2016.',
  'A clapboarded frame church on a stone foundation with an engaged tower over the main door on Montcalm Street. The 2016 form describes the auditorium with pews in two ranks, a gallery at the north end, a pressed-metal ceiling of 1903 and six large stained-glass windows of 1930, and Late Victorian woodwork in the 1893 social hall. The form is the source for the inside; whether the church opens to visitors was not checked.',
  '',
  'At the southwest corner of Montcalm and Ottawa streets. Service times not checked: no page of the congregation\'s own was read. Street parking.',
  [NR('16000164','Caldwell Presbyterian Church'),L('Lake George Chamber: Caldwell Presbyterian Church','https://lakegeorgechamber.com/businesses/caldwell-presbyterian-church')],brick='no',hours='?'),
N('st-james-episcopal-lake-george','St. James\' Episcopal Church, Lake George','Lake George','adk','worship','standing',43.42553,-73.71406,'exact','open','drive','','1866–1867',
  'The parish was founded in 1855, meeting first in the old courthouse; its first, wooden church of 1857 was blown down by a wind in 1866. The stone church that replaced it was built in 1866 and 1867, with the tower set at the side, and the Tudor Revival parish hall (Tuttle Hall) was added about 1909 or 1910. It belongs to the Episcopal Diocese of Albany and was listed on the National Register in 2013.',
  'A Gothic Revival stone church with a steep gable roof and an offset square tower under a tall octagonal spire, with the half-timbered parish hall attached. Interior not checked.',
  '',
  'At 172 Ottawa Street, at Montcalm Street. The parish\'s own site gives Sunday services; street parking.',
  [W('St. James Episcopal Church (Lake George, New York)'),L('St. James\' Church: history','https://stjameslg.com/history'),L('St. James\' Church, Lake George','https://stjameslg.com/'),L('Episcopal Diocese of Albany: St. James\' Church','https://albanyepiscopaldiocese.org/st-james-church-lake-george-ny/')],
  brick='no',hours='Sunday 9 a.m. Holy Eucharist'),
N('wiawaka-holiday-house','Wiawaka Holiday House','Lake George','adk','hotel','standing',43.42538,-73.69684,'site','view','drive','hotels','1876; Wiawaka from 1903',
  'Mary Wiltsie Fuller opened Wiawaka in 1903 as a place for affordable holidays for working women, mainly immigrant textile workers from Troy and Cohoes, on land Katrina and Spencer Trask handed over to her. The ground had held the United States Hotel and then F. G. Crosby\'s Crosbyside hotel; Crosby built the Second Empire house later called Fuller House in 1876, and the Trasks built Wakonda Lodge in 1905. It still runs as a nonprofit retreat for women and was listed on the National Register in 1998.',
  'Fuller House, which Wikipedia says is very little altered outside, and the other lodges on the lakeshore. HMdb has a marker for the Wiawaka bateaux, the 1758 boats sunk off the shore. Interior not checked.',
  'A women\'s holiday house still running since 1903.',
  'On Route 9L on the east shore, a private nonprofit retreat; Wikipedia says its workshops are open to the public, booked through its own calendar. Its rules for casual visitors were not checked: look from the road unless booked. The pin is Fuller House as OpenStreetMap maps it.',
  [W('Wiawaka Holiday House'),HM('17382','Wiawaka Bateaux')],conf='mixed',brick='?'),
N('mountainside-free-library','Mountainside Free Library','Queensbury','adk','civic','standing',43.44477,-73.6564,'site','open','drive','','1904',
  'The library was founded in 1894 and its building put up in 1904, through the Seelye and Eggleston families and Andrew Carnegie; the Lake George Chamber says it fulfilled the wish of the novelist Edward Eggleston, a summer resident nearby, for a library for his year-round neighbours. It was listed on the National Register in 2022.',
  'The small 1904 library on Route 9L at Joshua Rock Road, with the town\'s marker of 2008. What it is built of and the interior not checked.',
  '',
  'At 3090 Route 9L. Opening hours not checked: no page of the library\'s own was read.',
  [HM('148714','Mountainside Library'),L('Lake George Chamber: Mountainside Library','https://lakegeorgechamber.com/blog/mountainside-library-featured-in-flashbackfriday-series-8-14-2020')],brick='?',hours='?'),
# ---- Bolton ----
N('sembrich-opera-museum','The Sembrich (Marcella Sembrich Opera Museum)','Bolton Landing','adk','landmark','standing',43.54744,-73.66055,'site','open','drive','','1922–1924',
  'The Polish soprano Marcella Sembrich, who sang more than 450 performances at the Metropolitan Opera, had this teaching studio built on the lake in 1922 to 1924. It became a museum soon after her death in 1935 and holds summer concerts, talks and films. It was listed on the National Register in 2002.',
  'A one-storey stuccoed frame studio in a Spanish Revival style with a hipped roof and glassed-in porches, on 4.5 acres with a bathhouse, the curator\'s cottage, a lookout, stone shore walls, stone gate piers and an iron gate. Inside, exhibitions of the singer\'s career: art, costumes and papers.',
  'A diva\'s summer studio on the lake.',
  'At 4800 Lake Shore Drive (Route 9N), with a parking lot on the property. Its own page: admission free with a suggested $5 donation; the museum closes daily 12:30 to 2 p.m. for lunch and during daytime performances, while the grounds stay open; no dogs in the museum; flash not allowed.',
  [W('Marcella Sembrich Opera Museum'),L('The Sembrich: hours and admission','https://thesembrich.org/visit'),HM('18428','Sembrich Museum & Lakeside Grounds')],
  brick='no',hours='Closed for the season, reopening May 2027 (as read November 2026); season hours not given'),
N('sagamore-hotel-bolton','The Sagamore hotel, Green Island','Bolton Landing','adk','hotel','standing',43.55583,-73.6456,'site','open','drive','hotels','1883; rebuilt 1920s',
  'The Sagamore opened in 1883 on Green Island, built by Myron Brown and partners in the Green Island Improvement Company and named after a character in The Last of the Mohicans. It burned in 1893 and 1914. Wikipedia says it was rebuilt in the early 1920s under Robert Rheinlander; the Bolton Historical Society\'s marker gives the Sagamore Club as 1923 to 1929 and the present hotel as opened in 1930. It closed in 1981, and Norman Wolgin bought and restored it from 1983, the year it was listed on the National Register.',
  'The rambling white hotel on its island, reached by a bridge, with the town historical society\'s marker at the entrance on Sagamore Road. Interior not checked.',
  'A lake resort that burned twice and came back.',
  'A working resort hotel on a private island; the marker stands at the entrance on Sagamore Road. Whether non-guests may walk the grounds was not checked.',
  [W('The Sagamore'),HM('148263','The Historic Sagamore Hotel')],conf='mixed',brick='?',hours='?'),
# ---- Warrensburg ----
N('warrensburg-mills-district','Warrensburg Mills Historic District','Warrensburg','adk','industry','standing',43.48904,-73.77855,'area','public','walk','','c. 1820–1930',
  'All of Warrensburg\'s manufacturing grew up round the Schroon River and its dam north of the Judd Bridge: sawmills, a grist mill, a tannery, a peg mill that later made clothespins, a carding mill, a potash works and a paper mill (HMdb). The Register district of 1975 takes in the mill dam, the Emerson sawmill of about 1820, the grist mill, shirt factories of 1878 and 1898, an office of 1855, grain warehouses and the workers\' houses. Electricity was first made beside it in 1902 for the Hudson Valley Railway trolley to Lake George (Pomeroy marker).',
  'From River Street and the Warrensburg Historical Park at the dam: the mill buildings along the river, the Woolen Mill Bridge (about 1895, by the Croton Bridge Builders) and the Osborne Bridge (about 1930). The trolley power marker stands at 176 River Street; what is left of the power plant was not checked.',
  'A mill street on the Schroon, from sawmill to shirt factory.',
  'A public street with a small riverside park; the mill buildings are private and seen from River Street. The pin is the historical park marker by the dam.',
  [W('Warrensburg Mills Historic District'),HM('150149','Warrensburg Historical Park'),HM('133043','Trolley Power')],brick='?'),
N('warrensburg-hamlet-district','Hamlet of Warrensburgh Historic District (Main Street)','Warrensburg','adk','town','standing',43.49639,-73.77556,'site','public','walk','','c. 1840–1942',
  'A Register district of 2001 with 351 contributing buildings, covering the commercial core north of the Schroon River and the mill-side neighbourhood south of it. It includes the Woodward Block (about 1860), the Wills Block (about 1865), the bank at 138 Main Street (about 1927), the former Sturdevan\'s Bakery (about 1840), the Church of the Holy Cross (1864), the First Methodist Church (1904), the United Presbyterian Church (1840), the Richards Library (1900) and the school of 1942.',
  'Walk Main Street (US 9) for the commercial blocks and churches; Floyd Bennett Park with its 1930-31 bandstand, named for the Warrensburg-born aviator, and the town\'s historical markers. Individual buildings not checked inside.',
  'A whole Adirondack main street on the Register.',
  'Public streets; the buildings are private, churches and shops aside, and are seen from the sidewalk. The pin is Floyd Bennett Park on Main Street (the Register\'s own district point fell in woods).',
  [W('Hamlet of Warrensburgh Historic District'),HM('18107','Floyd Bennett Memorial')],brick='?'),
N('mixter-blacksmith-shop','Mixter Blacksmith Shop','Warrensburg','adk','industry','standing',43.49067,-73.76614,'site','view','drive','','c. 1840',
  'A blacksmith\'s shop built about 1840 in the Greek Revival style for a commercial business, and altered about 1890 in the Queen Anne style for mixed use. It is two storeys, built into a slope, of load-bearing local granite. It was listed on the National Register in 2002.',
  'The granite shop with its raised-seam metal roof. Two stone mounting blocks a short way west have HMdb markers of their own. Interior not checked.',
  '',
  'Ownership not checked; look from the road. The pin is the Register point, not checked against a street address.',
  [W('Mixter Blacksmith Shop'),HM('262047','Mounting Block')],conf='mixed',brick='no'),
# ---- Chester and Horicon ----
N('chestertown-historic-district','Chestertown Historic District (Fowler Homestead, Church of the Good Shepherd, Town Hall)','Chestertown','adk','town','standing',43.65195,-73.80109,'site','public','walk','','mid-1840s–1913',
  'A small Register district of 1977 at the centre of Chestertown with seven contributing buildings: the Fowler Homestead, a Greek Revival house of the mid-1840s, and its outbuildings; the Church of the Good Shepherd (1884, enlarged 1954); the Chester Town Hall; the Fowler cemetery; and the centennial monument of 1913. A boundary increase was approved in December 2025.',
  'The church, the town hall and the Fowler-Dains House side by side on Main Street, each with a Town of Chester Historical Society marker, and the war memorial. Interiors not checked.',
  '',
  'On Main Street (US 9); public street, the house is private. The pin is the church\'s marker.',
  [W('Chestertown Historic District (Chestertown, New York)'),HM('115213','Church of the Good Shepherd'),HM('115199','Fowler-Dains House'),HM('115216','Town Hall')],brick='?'),
N('heintzelman-library-brant-lake','Heintzelman Library, Brant Lake','Brant Lake','adk','civic','standing',43.67691,-73.74952,'exact','view','drive','','1906–1907',
  'The library was begun in 1906 and finished in 1907 with gifts from Emily Heintzelman, a Union Army widow, and residents of Horicon. It was built partly out over the mill pond on Spuyten Duyvil Brook. It served as the Horicon library until the new library opened in 2001, and is now the town historian\'s office and the town\'s history archive. Some 800 feet away, a marker gives the site of the grist mill Jud Barton built in 1865 and ran with his sons until 1937.',
  'A one-storey rustic building of stone and shingled wood with a slate roof and a small stone-and-wood porch, half over the water. The 2017 form says the sash and door are replacements and the original shelving is gone. The grist mill marker is on Route 8 across from Market Street; whether anything of the mill survives was not checked.',
  'A stone library built out over a mill pond.',
  'At 6615 State Route 8, across from the Horicon Baptist Church, with a narrow pull-off in front. Owned by the Town of Horicon; the town\'s historical society page refused the page tool, so the historian\'s hours were not checked.',
  [NR('100001249','Heintzelman Library'),L('Warren County: Horicon historic markers (PDF)','https://public.warrencountyny.gov/gis/HistoryStorymap/HoriconHistoricMarkers.pdf'),HM('200397','Heintzelman Library'),HM('77378','A Grist Mill')],brick='no'),
# ---- Johnsburg, Stony Creek, Hague ----
N('riverside-station-riparius','Riverside station, Riparius','Riparius','adk','rail','standing',43.66105,-73.89887,'exact','view','drive','stations','1913–1962',
  'Riverside was a stop on the Adirondack Railway from Saratoga Springs to North Creek by 1872; the Delaware and Hudson took the line over in 1889, and stages met trains here for the hamlets round about and the Schroon Lake steamers. In 1913 the Warrensburgh News called it the busiest station on the division, and the present station was finished that September. The D&H closed it in 1962. It was listed on the National Register in 1997.',
  'A long one-storey frame station with a hipped roof and covered platforms at each end, designed in a Prairie School manner, with a baggage room added between 1915 and 1924. Interior not checked.',
  'The busiest stop on the line to North Creek, by the Hudson.',
  'The station and about 40 miles of the old railroad belong to Warren County (Warren County Parks, Recreation & Railroad); Revolution Rail runs railbike trips to it in summer. Seen from Riverside Station Road off Route 8; keep off the track. The lot OpenStreetMap maps by the bridge end looked like a road shoulder on the aerial; parking not checked.',
  [W('Riverside station (New York)'),L('Pomeroy Foundation: Riverside Station','https://www.wgpfoundation.org/historic-markers/riverside-station/')],
  brick='no'),
N('stony-creek-methodist-church','Methodist Episcopal Church, Stony Creek','Stony Creek','adk','worship','standing',43.42561,-73.92979,'site','view','drive','','1858–1859',
  'A frame Greek Revival church built in 1858 and 1859, 32 feet wide and 48 deep on a stone foundation, with a square hip-roofed bell tower added in 1874. It was listed on the National Register in 2010.',
  'The plain white church with its 1874 tower. Wikipedia says the stained-glass windows date from the 1950s. Interior not checked.',
  '',
  'Whether the church is still used and when it opens were not checked; look from the road. The pin is the Register point.',
  [W('Methodist Episcopal Church (Stony Creek, New York)')],brick='no'),
N('silver-bay-association','Silver Bay Inn and the Silver Bay Association campus','Silver Bay','adk','hotel','standing',43.69534,-73.50581,'site','view','drive','hotels','1890s–1926',
  'A farmhouse here was enlarged in the 1890s into a lodge for 80 to 100 guests. Silas Paine, a Standard Oil executive, bought land beside it in 1897 and added a large resort wing in 1898 and cottages in 1900 and 1901. The YMCA bought it in 1904 (the conference association dates its work from 1902), and it took its present form in 1925 and 1926 under the architect William E. Clark. It was listed on the National Register in 1980.',
  'The Queen Anne inn on the west shore of Lake George and the campus round it; Wikipedia names Hepbron Hall (1901), Paine Hall (1895), the 700-seat auditorium (1909), the Helen Hughes Chapel (1921), Fisher Gymnasium (1917) and the boathouse. Interiors not checked.',
  'A Standard Oil man\'s resort that became a YMCA camp.',
  'A private YMCA conference and family retreat centre on Silver Bay Road off Route 9N, Hague. Its rules for people not staying there were not checked; look from the road unless booked. The pin is the inn as mapped in OpenStreetMap.',
  [W('Silver Bay Association Complex'),W('Silver Bay, New York')],conf='mixed',brick='?'),
]
